import * as React from "react";
import type { CrumbType } from "../Breadcrumb";
import clsx from "clsx";
import { SvgMpaIcon } from "../../../assets/icons";
import "./Crumb.scss";
import { Button } from "../../button";
import Separator from "../Separator/Separator";

export interface CrumbProps extends CrumbType {
  hoverStyle?: "normal" | "underline";
  colour?: "link" | "black" | "white";
  homeIcon?: keyof typeof SvgMpaIcon;
  showHomeLabel?: boolean;
  showSeparator?: boolean;
  multiline?: boolean;
  LinkComponent?: React.ComponentType<any>;
  separator?: React.ReactNode;
  isFirst?: boolean;
  isLast?: boolean;
}

const Crumb: React.FC<CrumbProps> = ({
  hoverStyle,
  colour,
  homeIcon = "Home",
  showHomeLabel = false,
  showSeparator = true,
  multiline,
  label,
  to,
  LinkComponent,
  separator,
  isFirst,
  isLast,
}) => {
  const firstCrumb = (
    <>
      <Button
        id="breadcrumb-label-button"
        className={clsx(
          "breadcrumb-label-button", {
          "breadcrumb-no-label-icon": !showHomeLabel,
          "breadcrumb-label-black": colour === "black",
          "breadcrumb-label-white": colour === "white",
          },
          hoverStyle
        )}
        leadingIcon={homeIcon}
        btnType="text"
        label={showHomeLabel && label ? label : undefined}
      >
      
      </Button>
    </>
  );
  const showLabel = () => {
    return isFirst ? (
      firstCrumb
    ) : (
      <Button
        id="breadcrumb-label-button"
        className={clsx(
          "breadcrumb-label-button", {
          "breadcrumb-label-black": colour === "black",
          "breadcrumb-label-white": colour === "white",
          },
        hoverStyle
        )}
        btnType="text"
        label= {label}>       
      </Button>
    );
  };
  const getLink = () => {
    if (LinkComponent) {
      return <LinkComponent to={to}>{showLabel()}</LinkComponent>;
    }
    return <a href={to}>{showLabel()}</a>;
  };
  const getLast = () => {
    if (isFirst) {
      return firstCrumb;
    }
    if (multiline) {
      return null;
    }
    return (
      <span
        className={clsx(
          "breadcrumb-label-last", {
          "breadcrumb-label-black": colour === "black",
          "breadcrumb-label-white": colour === "white",
        },
        hoverStyle
        )}
      >
        {label}
      </span>
    );
  };

  return (
    <>
      <li
        className={clsx("breadcrumb-li", {
          "breadcrumb-li-first": isFirst,
          "breadcrumb-li-last": isLast,
        })}
      >
        {isLast ? getLast() : getLink()}
      </li>
      {showSeparator && <Separator colour={colour} separator={separator} />}
    </>
  );
};

export default Crumb;
